#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using i128 = __int128_t;

constexpr ll MOD = 998244353LL;
constexpr ll MODD = 1000000007LL;
constexpr int MAX_N = 1000005;
constexpr ll INF = 1000000000000000000LL;

ll p10[15];
vector<string> groups[7];
vector<ll> sorted_vals[7][7];
ll prefix[7][7];

inline ll to_int(const string& s) {
    ll res = 0;
    for (char c : s) res = res * 10 + (c - '0');
    return res;
}

inline i128 solve(const string& prefix, int rem, ll& cnt) {
    if (rem == -1) return 0;
    int L = rem / 2, R = rem - L;
    if (rem == 1) { L = 1; R = 0; }

    i128 res = (cnt - to_int(prefix) + MOD * MOD) % MOD;
    cnt++;

    for (const string& left : groups[L]) {
        string comb = prefix + left;
        res += (-to_int(comb) + cnt + MOD * MOD) % MOD;
        cnt++;

        if ((int)left.size() == L) {
            ll val = to_int(comb) % MOD;
            for (int sz = 1; sz <= R; ++sz) {
                ll cst = (-val * p10[sz] + cnt + MOD * MOD) % MOD;
                auto& vec = sorted_vals[R][sz];
                int pos = lower_bound(vec.begin(), vec.end(), MOD - cst) - vec.begin();
                res += (i128)vec.size() * cst + prefix[R][sz] - (i128)MOD * (vec.size() - pos);
            }
            cnt += groups[R].size();
        }
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);

    ll n; cin >> n;
    string s = to_string(n);
    int N = s.size();

    p10[0] = 1;
    for (int i = 1; i <= 14; ++i) p10[i] = p10[i-1] * 10;

    for (int i = 0; i < MAX_N; ++i) {
        string num = to_string(i);
        string pad = num;
        while ((int)pad.size() <= 6) {
            pad = "0" + pad;
            groups[pad.size()].push_back(pad);
        }
    }

    for (int len = 1; len <= 6; ++len) {
        for (const auto& prev : groups[len-1]) groups[len].push_back(prev);
        sort(groups[len].begin(), groups[len].end());

        for (int j = 0; j < (int)groups[len].size(); ++j) {
            ll val = (j - stoi(groups[len][j]) + MOD) % MOD;
            sorted_vals[len][groups[len][j].size()].push_back(val);
        }

        for (int sz = 1; sz <= len; ++sz) {
            sort(sorted_vals[len][sz].begin(), sorted_vals[len][sz].end());
            for (ll v : sorted_vals[len][sz]) prefix[len][sz] += v;
        }
    }

    vector<pair<string, int>> queries;
    string cur = "";

    for (int i = 0; i < (int)s.size(); ++i) {
        for (int d = 0; d <= 9; ++d) {
            if (d == s[i] - '0') continue;
            if (i == 0 && d == 0) continue;

            cur += char('0' + d);
            if (d <= s[i] - '0') {
                queries.emplace_back(cur, (int)s.size() - i - 1);
            } else {
                queries.emplace_back(cur, (int)s.size() - i - 2);
            }
            cur.pop_back();
        }
        cur += s[i];
        queries.emplace_back(cur, 0);
    }

    ll cnt = 1;
    i128 ans = 0;
    sort(queries.begin(), queries.end());

    for (const auto& q : queries) {
        if (s[q.first.size() - 1] == q.first.back()) {
            ans += (-to_int(q.first) + cnt + MOD * MOD) % MOD;
            cnt++;
            continue;
        }
        ans += solve(q.first, q.second, cnt);
    }

    ans %= MODD;
    cout << (ll)ans << '\n';

    return 0;
}
